<template><main class="video-detail"><a-spin :spinning="loading"><a-alert v-if="error" type="error" :message="error" show-icon/><template v-if="record"><router-link to="/?media=video">← 视频图库</router-link><h1>{{record.name}}</h1><video class="player" :src="`${videoBase}/videos/${record.id}/media`" :poster="`${videoBase}/videos/${record.id}/media?kind=poster`" controls preload="metadata"/><div class="review-info"><a-tag :color="record.review_status===1?'green':record.review_status===2?'red':'blue'">{{record.review_status===1?'审核通过':record.review_status===2?'审核未通过':'待审核'}}</a-tag><span>审核人：{{record.reviewer_name||'待审核'}}</span><p>{{record.review_message}}</p><small v-if="record.review_source==='ai'||record.review_source==='pending'">视频按每秒抽帧及首尾帧审核，管理员可再次审核。</small><a-button v-if="admin" :loading="reviewing" @click="requestAiReview">重新AI审核</a-button></div><div class="details"><span>{{frameTime(record.metadata.frames,record.metadata.fps)}} · {{record.metadata.width}} × {{record.metadata.height}} · 项目 v{{record.revision}}</span><a-space><a-button :href="`${videoBase}/videos/${record.id}/media?download=1`">下载 MP4</a-button><a-button type="primary" @click="router.push(`/video/editor/${record.project_id}`)">继续编辑</a-button><a-button v-if="admin" @click="review(1)">人工通过</a-button><a-button v-if="admin" danger @click="review(2)">人工拒绝</a-button></a-space></div></template></a-spin></main></template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useLoginUserStore} from '@/stores/useLoginUserStore';import {videoApi,videoBase,frameTime,type VideoRecord} from '@/api/videoEditor'
const route=useRoute(),router=useRouter(),record=ref<VideoRecord>(),reviewing=ref(false),loading=ref(true),error=ref(''),store=useLoginUserStore(),admin=computed(()=>store.loginUser.userRole==='admin')
async function load(){try{record.value=await videoApi(`/videos/${route.params.id}`)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function review(status:number){if(reviewing.value)return;reviewing.value=true;try{await videoApi(`/videos/${record.value!.id}/review`,{reviewStatus:status});await load()}catch(e){error.value=(e as Error).message}finally{reviewing.value=false}}
async function requestAiReview(){if(reviewing.value)return;reviewing.value=true;try{await videoApi(`/videos/${record.value!.id}/ai-review`,{});await load()}catch(e){error.value=(e as Error).message}finally{reviewing.value=false}}
let poll:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await load();poll=setInterval(()=>{if(record.value?.review_status===0&&!reviewing.value)void load()},5000)})
onBeforeUnmount(()=>{if(poll)clearInterval(poll)})
</script>
<style scoped>
.review-info{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:16px 0;color:#718096}
.review-info p{flex-basis:100%;margin:0}.review-info small{flex:1}
</style>
<style scoped>.video-detail{max-width:1100px;margin:20px auto;padding:12px}.player{width:100%;max-height:60vh;background:#080b10;border-radius:12px}.details{display:flex;justify-content:space-between;align-items:center;margin-top:20px;gap:12px;flex-wrap:wrap}.details span{color:#77808f}</style>
